"""Simulator oracle: loops with a known fault, generated by the Simulator dynamics.

Each case is one loop of the OPC UA plant simulator (``tests/oracles/simulator.py``) run for
eight hours at a 5 s integration step and recorded every 10 s, as the Simulator's historian does.
The analysis window is the last six hours (``WINDOW_END`` minus ``tests.plant.HOURS``); the first
two hours let the loop settle. Two faults the simulator has no behaviour for are applied to its
output the way the Simulator's scenarios do: a frozen transmitter holds its last measurement
(``sensor.frozen``), and tuning-driven oscillation is the healthy loop with an aggressive
controller.

The expected verdict of each case comes from how it was built, never from what the methods
return: ``flags`` lists methods that must report ``warning`` or ``bad``, ``clear`` methods that
must not flag the loop (``ok``, or ``not_applicable``/``insufficient_data`` when the method
cannot judge it: an honest "cannot tell" is not a false alarm), and ``rejected`` means the data quality gate must refuse the data (every CPM
method ``insufficient_data``, loop status ``no_data``).
"""

from __future__ import annotations

import math
from dataclasses import dataclass, replace
from datetime import datetime, timedelta, timezone

import numpy as np
import pandas as pd

from tests.oracles.simulator import LoopDefinition, initial_state, simulate_step
from tests.plant import HOURS, SAMPLE_SECONDS, PlantFake

# 07:00-13:00 UTC: the healthy loop's setpoint toggles at 06:00 (in the settling time) and
# the manual loop is in MAN from 04:00 to 10:00, so half of the window is manual.
WINDOW_END = datetime(2026, 10, 1, 13, 0, tzinfo=timezone.utc)
SETTLE_HOURS = 2
STEP_SECONDS = 5.0

