def simulate(case: Case) -> dict[str, pd.Series]:
    """PV, SP, OP and MODE of one case over the settling time and the window."""

    definition = case.definition
    state = initial_state(definition)
    start = WINDOW_END - timedelta(hours=HOURS + SETTLE_HOURS)
    window_start = WINDOW_END - timedelta(hours=HOURS)
    steps = int((WINDOW_END - start).total_seconds() // STEP_SECONDS)
    record_every = int(SAMPLE_SECONDS // STEP_SECONDS)
    stamps: list[datetime] = []
    rows: list[dict] = []
    frozen_pv: float | None = None
    for i in range(1, steps + 1):
        stamp = start + timedelta(seconds=i * STEP_SECONDS)
        values = simulate_step(definition, state, stamp, STEP_SECONDS)
        if case.frozen:
            # The transmitter fails one hour before the window and holds its last value;
            # the controller keeps acting on the frozen measurement.
            if frozen_pv is None and stamp >= window_start - timedelta(hours=1):
                frozen_pv = float(values["PV"])
            if frozen_pv is not None:
                state.measured_pv = frozen_pv
                values["PV"] = frozen_pv
        if i % record_every == 0 and stamp >= window_start:
            stamps.append(stamp)
            rows.append(values)
    index = pd.DatetimeIndex(stamps)
    tag = definition.loop_id
    series = {
        f"{SOURCE}:{tag}.{name}": pd.Series([float(row[name]) for row in rows], index=index)
        for name in ("PV", "SP", "OP")
    }
    series[f"{SOURCE}:{tag}.MODE"] = pd.Series(
        [str(row["MODE"]) for row in rows], index=index, dtype=object
    )
    for name, values in series.items():
        if name.endswith((".PV", ".SP", ".OP")):
            assert np.isfinite(values.to_numpy()).all() and not math.isnan(values.iloc[0])
    return series


# The source the simulator's signals are read from: API v1 ids are ``<source id>:<tag>``.
SOURCE = "simulator"


def make_fake() -> PlantFake:
    """A PlantCraft serving every case as a loop asset, as the simulator would through it."""

    assets: list[dict] = [
        {"id": "sim", "name": "Simulator", "kind": "site", "parent_id": None, "attributes": {}},
        {"id": "oracle", "name": "Oracle", "kind": "unit", "parent_id": "sim", "attributes": {}},
    ]
    signals: list[dict] = []
    series: dict[str, pd.Series] = {}
    for case in CASES:
        definition = case.definition
        tag = definition.loop_id
        assets.append(
            {
                "id": case.case_id,
                "name": tag,
                "kind": "loop",
                "parent_id": "oracle",
                "attributes": {"description": definition.service},
                "signals": {
                    role: f"{SOURCE}:{tag}.{role.upper()}" for role in ("pv", "sp", "op", "mode")
                },
            }
        )
        for role, unit in (("PV", definition.pv_unit), ("SP", definition.pv_unit), ("OP", "%")):
            signals.append(
                {
                    "id": f"{SOURCE}:{tag}.{role}",
                    "name": f"{definition.name} {role}",
                    "source": SOURCE,
                    "unit": unit,
                    "description": f"{definition.name} {role}",
                    "low": 0.0,
                    "high": 100.0,
                }
            )
        signals.append(
            {
                "id": f"{SOURCE}:{tag}.MODE",
                "name": f"{definition.name} MODE",
                "source": SOURCE,
                "unit": "",
                "description": f"{definition.name} MODE",
            }
        )
        series.update(simulate(case))
    return PlantFake(assets=assets, signals=signals, series=series, now=WINDOW_END)


FLAGGED = {"warning", "bad"}
NOT_FLAGGED = {"ok", "not_applicable", "insufficient_data"}


def unmet(case: Case, status: str, results: dict[str, dict]) -> list[str]:
    """What a round got wrong about one case; an empty list is a pass."""

    problems: list[str] = []
    gate_rejected = any(
        item.get("metrics", {}).get("apt") is False
        for method_id, item in results.items()
        if method_id.startswith("dq_")
    )
    if case.rejected:
        if not gate_rejected or status != "no_data":
            problems.append(f"gate accepted the data (loop status {status})")
        ran = [
            method_id
            for method_id, item in results.items()
            if not method_id.startswith("dq_")
            # Sampling quality judges the record itself (rates, gaps), beside the gate.
            and method_id != "sampling_quality"
            and item["status"] != "insufficient_data"
        ]
        if ran:
            problems.append(f"CPM methods ran on rejected data: {', '.join(ran)}")
        return problems
    if gate_rejected:
        problems.append("gate rejected usable data")
    for method_id in case.flags:
        got = results.get(method_id, {}).get("status", "missing")
        if got not in FLAGGED:
            problems.append(f"{method_id} should flag the loop, got {got}")
    for method_id in case.clear:
        got = results.get(method_id, {}).get("status", "missing")
        if got not in NOT_FLAGGED:
            problems.append(f"{method_id} should not flag the loop, got {got}")
    return problems
